contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        address ownerBefore = c.owner();

        bool reverted;
        if (caller == ownerBefore) {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            (bool ok, ) = address(c).call(
                abi.encodeWithSignature("transferOwnership(address)", newOwner)
            );
            reverted = !ok;
        }

        if (msg.sender == ownerBefore) {
            if (newOwner == address(0)) {
                assert(reverted);
            } else {
                assert(!reverted);
                assert(c.owner() == newOwner);
            }
        } else {
            assert(reverted);
        }
    }
}

