contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address ownerBefore = c.owner();
        bool callerIsOwner = (msg.sender == ownerBefore);
        bool shouldRevert = !(callerIsOwner && newOwner != address(0));

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();
        bool ownerUnchanged = (ownerAfter == ownerBefore);
        bool ownerSet = (ownerAfter == newOwner);

        assert(
            (reverted == shouldRevert) &&
            (reverted ? ownerUnchanged : ownerSet)
        );
    }
}

