contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public {
        // Setup: the owner of c is this test contract, so addReward is callable;
        // adding an unknown reward token initializes lastUpdateTime and periodFinish to block.timestamp.
        c.addReward(token);

        // Read the observable return value from the public getter/entry point.
        uint40 finish = c.rewardPeriodFinish(token);

        assert(finish <= uint40(block.timestamp) + 86400 * 7);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public {
        // Setup: register the reward token through the public entry point.
        // A fresh C has lastUpdateTime == 0 for any token, so addReward succeeds.
        c.addReward(token);

        // Read the observable return value from the focus entry point.
        uint40 finish = c.rewardPeriodFinish(token);

        // General rule: any finish time ever returned by rewardPeriodFinish
        // is at most now + 7 days (DURATION), for every possible input.
        assert(finish <= uint40(block.timestamp) + 86400 * 7);
    }
}

