contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address rewardToken, uint256 amount) public {
        // caller and rewardToken come from the fuzzer; set up the exact sender and register
        // the reward token so the only remaining deciding factor is (msg.sender, amount).
        require(rewardToken != address(0), "token must be a real address");

        // Register rewardToken as a known reward token by having the owner call addReward.
        // c is owned by this test contract, so this call succeeds and is the same call we
        // can use below as a baseline for the unregistered-token revert case.
        c.addReward(rewardToken);

        // Ensure the reward distributor is the fuzzer-provided caller so that the successful
        // path is reachable for that caller; if caller is zero we do not treat it as distributor.
        if (caller != address(0)) {
            c.setRewardDistributor(caller);
        }

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: notifyRewardAmount succeeds exactly when the caller is the configured
        // distributor, the amount is positive, and the token was registered via addReward.
        bool expectedSuccess = (caller != address(0)) && (amount > 0) && (rewardToken != address(0));
        assert(reverted != expectedSuccess);
    }

    receive() external payable {}
}

