contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address oldStaking, uint256 amount) public returns (uint256 beforeBal, uint256 beforeSupply, bool reverted) {
        require(caller != address(0), "bad caller");
        require(oldStaking != address(0), "bad old staking");
        require(oldStaking != address(c), "old == c");

        // Record state before the deciding call.
        beforeSupply = c.totalSupply();
        beforeBal = c.balanceOf(caller);

        address currentMigrator = c.migrator();

        // The deciding call: caller is NOT the migrator.
        if (caller == address(this)) {
            // Make sure this contract is not the migrator in this branch.
            reverted = (currentMigrator == address(this));
            if (!reverted) {
                try c.migrateStake(oldStaking, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // Call through a low-level call so we can supply a different msg.sender.
            (bool ok, ) = address(c).call(
                abi.encodeWithSelector(C.migrateStake.selector, oldStaking, amount)
            );
            reverted = !ok;
        }

        // The only way a non-migrator call to migrateStake can succeed is if caller == currentMigrator.
        // But we drove with caller != address(this); the contract itself always reverts.
        assert(reverted && c.totalSupply() == beforeSupply && c.balanceOf(caller) == beforeBal);
    }

    receive() external payable {}
}

