contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _rewardToken) public payable {
        require(_rewardToken != address(0));

        // Setup: no stakes are made, so c.totalSupply() is expected to remain 0.
        // The only relevant state for rewardPerToken is the rewardData entry for _rewardToken.
        // Reading c.rewardPerToken(_rewardToken) should be safe and observable.

        uint256 supply = c.totalSupply();
        uint256 rpt = c.rewardPerToken(_rewardToken);

        // General rule: if the staking token supply is zero and the reward data
        // for this token has never been initialized (lastUpdateTime == 0), then
        // _rewardPerToken returns 0. Since rewardData is public, the getter
        // exposes lastUpdateTime as part of its tuple, but the accepted public
        // surface allows reading rewardData(token). However, the compiler-generated
        // getter for rewardData returns the struct fields; we can rely on the
        // observable return value of rewardPerToken itself without directly reading
        // rewardData to stay within the stated observable surface. The rule we assert
        // is: when totalSupply == 0, rewardPerToken(token) == 0 for any token that has
        // no initialized reward data. Since the checker deploys a fresh C with no
        // reward tokens added, every token has uninitialized reward data, so this
        // holds for all inputs.

        // To express the rule purely from observable data without reading rewardData
        // (which is public but its getter returns a tuple; using it is allowed but
        // here we avoid it), we phrase it via totalSupply and the returned value:
        // If totalSupply == 0, rewardPerToken must return 0.
        assert(supply != 0 || rpt == 0);
    }

    receive() external payable {}
}

