contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _rewardToken, uint256 _amount, address _staker, uint256 _stakeAmount) public {
        // Arrange: add a reward token so its rewardData.lastUpdateTime != 0,
        // making it a valid reward token for rewardPerToken reads.
        c.addReward(_rewardToken);

        // Ensure totalSupply() is zero before the read, so the totalSupply==0 branch is taken.
        require(c.totalSupply() == 0, "precondition: no stake yet");

        // Snapshot observable before-values.
        uint256 storedBefore = c.rewardData(_rewardToken);
        uint256 totalSupplyBefore = c.totalSupply();
        uint40 periodFinishBefore = c.rewardPeriodFinish(_rewardToken);

        // The deciding read-only call under test.
        uint256 rpt = c.rewardPerToken(_rewardToken);

        // General rule for the totalSupply == 0 branch:
        // rewardPerToken returns rewardPerTokenStored exactly, regardless of periodFinish/rate/time.
        // rewardPerTokenStored is not directly exposed, but when totalSupply == 0 it must equal
        // the returned value, and the returned value must not depend on periodFinish or rewardRate.
        assert(
            totalSupplyBefore == 0
                ? rpt == storedBefore
                : true
        );

        // Stronger, context-independent observable: when totalSupply() == 0, the returned
        // rewardPerToken is stable across two consecutive reads (no accrual can be applied),
        // and equals the value returned by the first read.
