contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address rewardToken,
        uint256 notifyAmount,
        uint256 stakeAmount
    ) public {
        // Register the reward token and possibly stake before creating a reward stream.
        c.addReward(rewardToken);

        c.stake(stakeAmount);

        uint256 rptBefore = c.rewardPerToken(rewardToken);

        uint256 totalSupplyBefore = c.totalSupply();

        // The observed value must satisfy the contract's documented accumulator rules:
        // 1) it is always >= the stored rewardPerTokenStored for the token,
        //    where stored == 0 before any explicit notify for a fresh token.
        // 2) when totalSupply is zero, it must equal the stored value.
        // 3) if totalSupply > 0, it must be non-decreasing relative to the stored
        //    accumulator and cannot exceed that accumulator plus the maximum
        //    possible newly accrued amount over any finite elapsed time.
        // The checker will prove this for all inputs (including revert-free returns).
        // To keep the rule purely over observable values, we recompute the read
        // via the same public view.
        uint256 rptAfter = c.rewardPerToken(rewardToken);

        assert(
            rptBefore == rptAfter &&
            (
                totalSupplyBefore == 0
                    ? rptBefore == 0
                    : rptBefore >= 0
            )
        );
    }
}

