    function run(address token, uint256 amount, bool setDistributor) public {
        // Make the test contract the distributor so the call can pass the distributor check.
        if (setDistributor) {
            c.setRewardDistributor(address(this));
        }

        bool knownBefore = isKnownReward(constructUnknownCheckFalse());

        bool reverted;
        try c.notifyRewardAmount(token, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the reward token was already known before the call (lastUpdateTime != 0),
        // or amount is zero, or the test contract is not the distributor, the call must revert.
        // Otherwise, the call must succeed.
        bool callerIsDistributor = setDistributor;
        bool shouldSucceed = callerIsDistributor && amount > 0 && !knownBefore;
        assert(reverted == !shouldSucceed);
    }

    function constructUnknownCheckFalse() internal pure returns (address) {
        return address(0);
    }

    function isKnownReward(address rewardToken) internal view returns (bool) {
        // rewardData(rewardToken) is a public getter for the Reward struct.
        // lastUpdateTime is the third field; its value is nonzero for tokens added via addReward.
        (, , uint40 lastUpdateTime, ) = c.rewardData(rewardToken);
        return lastUpdateTime != 0;
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token, uint256 amount, bool setDistributor) public {
        c.setRewardDistributor(address(this));

        (, , uint40 lastUpdateTimeBefore, ) = c.rewardData(token);
        bool knownBefore = lastUpdateTimeBefore != 0;

        c.setRewardDistributor(setDistributor ? address(this) : address(0));

        bool reverted;
        try c.notifyRewardAmount(token, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool callerIsDistributor = setDistributor;
        bool shouldSucceed = callerIsDistributor && amount > 0 && !knownBefore;
        assert(reverted == !shouldSucceed);
    }

    receive() external payable {}
}
